settings.custom_liquid:
{{ 'reliefroll.css' | asset_url | stylesheet_tag }}
<style>
  .product .product__info-container > * + * { margin-top: 1.4rem; }
  .product .price--large { font-size: 2.8rem; font-weight: 700; }
  .product .price__badge-sale { background: #e0584b; color: #fff; border: 0; }
  .product .product-form__submit {
    min-height: 58px; border-radius: 999px; background: #0b8a86 !important; color: #fff !important;
    font-size: 17px; font-weight: 700; box-shadow: 0 10px 24px rgba(11,138,134,.28);
  }
  .product .product-form__submit:hover { background: #087571 !important; }
  .product .product-form__submit::after,
  .product .shopify-payment-button__button::after { box-shadow: none !important; }
  .product .shopify-payment-button__button { border-radius: 999px; overflow: hidden; }
  .product .product__media-item .media,
  .product .thumbnail { border-radius: 14px; overflow: hidden; }
</style>
<p class="rr-eyebrow rr-pdp-eyebrow">Pour les raideurs du bas du dos au réveil</p>
<h1 class="rr-pdp-title">ReliefRoll™ — le bas du dos apaisé dès le réveil, en 10 minutes</h1>

{%- assign v = product.selected_or_first_available_variant -%}
{%- if v.compare_at_price > v.price -%}
  {%- assign rr_saving = v.compare_at_price | minus: v.price -%}
  <div class="rr-pdp-offer">{% render 'rr-icon', name: 'gift' %}<span>Offre de lancement : vous économisez <strong>{{ rr_saving | money }}</strong> aujourd'hui.</span></div>
{%- endif -%}
